const aspValidation = new aspnetValidation.ValidationService();
aspValidation.debounce = 500;

aspValidation.bootstrap();
 /**
 * Override to ensure formAction from button is set as the forms submit action.
 * https://github.com/haacked/aspnet-client-validation/blob/main/dist/aspnet-validation.js#L497
 */
aspValidation.submitValidForm = function (form, submitEvent) {
    var newEvent = new SubmitEvent('submit', submitEvent);
    if (form.dispatchEvent(newEvent)) {
        if (submitEvent.submitter.hasAttribute("formaction")) {
            form.action = submitEvent.submitter.formAction;
        }
        form.submit();
    }
};
